"""Isolated #140 material in #144 crank/contact and exact #148 planner. Frozen inputs stay unchanged."""
from pathlib import Path
import argparse
R=Path(__file__).resolve().parents[2];T=Path(__file__).parent
def outputs():
 for source,name in [('tools/shared-world-speedway/StandingStart144/Contact144.cs','Contact149'),('tools/shared-world-speedway/PlannerPerformance148/ForecastContact148.cs','ForecastContact149')]:
  s=(R/source).read_text(encoding='utf-8').replace('class Contact144','class Contact149').replace('class ForecastContact148','class ForecastContact149')
  s=s.replace('namespace Speed148;','using Speed148;\nnamespace Limits149;')
  # Material adapter has the old call signature, but receives actual unchanged Fz/mu.
  s=s.replace('RearWheelDynamics.Evaluate(ur,wr,','Wheel149.Evaluate(ur,wr,')
  s=s.replace('rearBudgetNewtons:rearBudget','normal:tyreLoads!.RearNormalNewtons,mu:tyreLoads.EffectiveFrictionCoefficient')
  s=s.replace('rearBudgetNewtons:load is null&&tyreLoads is null?null:rearBudget','normal:tyreLoads!.RearNormalNewtons,mu:tyreLoads.EffectiveFrictionCoefficient')
  s=s.replace('        var geometry=p.TwoContactBike', '        if(!p.EnableLoadBasedTyreGrip)throw new ArgumentException("Study149 B requires explicit load-based grip.");\n        var geometry=p.TwoContactBike')
  yield R/'tools/shared-world-speedway/TyrePhysics149'/f'{name}.cs','// Generated by generate149.py: only rear material/solver changes; original engine, front, capacity and geometry.\n'+s
 s=(R/'tools/planner-speed-root-cause/FastPredictor148.cs').read_text(encoding='utf-8').replace('namespace Speed148;','using Speed148;\nnamespace Limits149;').replace('FastPredictor148','FastPredictor149').replace('ForecastContact148.Forces','ForecastContact149.Forces')
 yield T/'FastPredictor149.cs',s
 s=(R/'tools/planner-speed-root-cause/ExactRuntime148.cs').read_text(encoding='utf-8').replace('namespace Speed148;','using Speed148;\nnamespace Limits149;').replace('ExactRuntime148','ExactRuntime149').replace('FastPredictor148','FastPredictor149')
 yield T/'ExactRuntime149.cs',s
 s=(R/'tools/planner-speed-root-cause/DiagnosticWorld148.cs').read_text(encoding='utf-8').replace('DiagnosticWorld148','DiagnosticWorld149')
 s=s.replace('readonly StandingOptions144 options;', 'readonly bool separated,observeBeyondBeta;\n    readonly StandingOptions144 options;')
 s=s.replace('RiderSpec? diagnosticRider=null){','RiderSpec? diagnosticRider=null,bool separated=false,bool observeBeyondBeta=false){\n        this.separated=separated;this.observeBeyondBeta=observeBeyondBeta;')
 s=s.replace('Contact144.Forces(', 'Forces(')
 # Same call shape for native A and B, including the implicit clutch wheel callback.
 marker='    FreeRacingInput Input(int i)'
 wrapper='''    TwoContactForces Forces(RiderView v,RiderSpec spec,TrackFrame frame,TrackStateSnapshot surface,WorldParameters p,double time,float mass,RearWheelState wheel,TwoContactBikeState state,float seconds,float? steeringOverride=null,float? inertia=null,CrankClutch144? powertrain=null,double releaseAt=0)
        =>separated?Contact149.Forces(v,spec,frame,surface,p,time,mass,wheel,state,seconds,steeringOverride:steeringOverride,inertia:inertia,powertrain:powertrain,releaseAt:releaseAt):Contact144.Forces(v,spec,frame,surface,p,time,mass,wheel,state,seconds,steeringOverride:steeringOverride,inertia:inertia,powertrain:powertrain,releaseAt:releaseAt);
'''
 s=s.replace(marker,wrapper+marker)
 s=s.replace('if(Math.Abs(views[i].SlideRadians)>Math.PI/4)reason=', 'if(!observeBeyondBeta&&Math.Abs(views[i].SlideRadians)>Math.PI/4)reason=')
 # All original physical guards remain. Extra observer checks do not alter forces.
 s=s.replace('string? reason=null;', '''string? reason=null;
                if(!double.IsFinite(wheelDelta)||!double.IsFinite(crankDelta)||!double.IsFinite(excess)||!double.IsFinite(powers[i].ClutchHeatJoules))throw new InvalidOperationException("nonfinite extended energy ledger");
                if(powers[i].ClutchHeatJoules<-.001||wheels[i].Prepared.LongitudinalLossJoules<-.001||wheels[i].Prepared.RearUtilization>1.000001)throw new InvalidOperationException("nonpassive extended contact");''')
 yield T/'DiagnosticWorld149.cs',s
 s=(T/'Baseline149.cs').read_text(encoding='utf-8').replace('class Baseline149','class Native149').replace('ExactRuntime148','ExactRuntime149').replace('new DiagnosticWorld145(', 'new DiagnosticWorld149(').replace('MaximumSeconds:120)))','MaximumSeconds:120),separated:true))')
 s=s.replace('Unchanged Contact144/crank/tyres/Box2D.', '#140 separated rear material + midpoint wheel inside unchanged #144 crank/clutch. Front, mu/Fz and Box2D unchanged.')
 yield T/'Native149.cs',s
def main():
 a=argparse.ArgumentParser();a.add_argument('--check',action='store_true');args=a.parse_args()
 for p,s in outputs():
  if args.check:assert p.read_text(encoding='utf-8')==s,p
  else:p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf-8',newline='\n')
if __name__=='__main__':main()
